is_weak_algorithm_str(str) {
    lowered := lower(str)
    alg := weak_algorithms[_]
    lowered == alg
}

contains_weak_algorithm(str) {
    lowered := lower(str)
    alg := weak_algorithms[_]
    regex.match(sprintf(".*\\b%s\\b.*", [alg]), lowered)
}

has_crypto_context(name) {
    lowered := lower(name)
    ctx := crypto_attr_names[_]
    lowered == ctx
} else {
    lowered := lower(name)
    ctx := crypto_attr_names[_]
    contains(lowered, ctx)
