    ctx := {"crypt", "encrypt", "cipher", "hash", "digest", "mac", "tls", "ssl", "hmac", "sign", "kdf", "kek", "password", "auth", "key", "algorithm", "integrity"}
    contains(lowered, ctx[_])
}

check_string_value(val) {
    val.ir_type == "String"
    contains_weak_algorithm(val.value)
